// ====================================================================
// استخراج بيانات الرسالة والمرفق من جروب البورتال المخصص (Hub Group)
// ====================================================================
const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const message = data.message || {};
const messageType = data.messageType || '';

// استخراج الكابشن من الرسالة المحولة أو الأصلية
let caption = '';
if (message.conversation) caption = message.conversation;
else if (message.extendedTextMessage?.text) caption = message.extendedTextMessage.text;
else if (message.documentMessage?.caption) caption = message.documentMessage.caption;
else if (message.imageMessage?.caption) caption = message.imageMessage.caption;
else if (message.videoMessage?.caption) caption = message.videoMessage.caption;

// دعم الكابشن للرسائل المعاد توجيهها (Quoted / Forwarded Context)
const contextInfo = message.extendedTextMessage?.contextInfo || message.documentMessage?.contextInfo;
if (contextInfo?.quotedMessage) {
  const q = contextInfo.quotedMessage;
  const quotedText = q.conversation || q.extendedTextMessage?.text || q.documentMessage?.caption || '';
  if (quotedText && !caption) caption = quotedText;
  else if (quotedText) caption = `${caption} | محتوى محوّل: ${quotedText}`;
}

// استخراج المرفق واسم الملف
const docMsg = message.documentMessage || message.documentWithCaptionMessage?.message?.documentMessage;
const fileName = docMsg?.fileName || data.fileName || '';
const mimetype = docMsg?.mimetype || data.mimetype || 'application/pdf';

// معلومات الشات
const remoteJid = data.key?.remoteJid || '';
const isGroup = remoteJid.endsWith('@g.us');
const groupName = data.groupName || data.chatName || '';

// ====================================================================
// تحديد جروب البورتال المخصص:
// يعتبر الشات هو جروب البورتال لو اسمه يحتوي 'بورتال' أو 'portal'
// أو لو قمت بتحديد الـ JID الخاص بالجروب هنا
// ====================================================================
const TARGET_HUB_JID = ''; // اختياري: ضع معرّف الجروب هنا إن وجد
const isHubGroup = (TARGET_HUB_JID && remoteJid === TARGET_HUB_JID) ||
                   (groupName && /بورتال|portal|مواد|materials/i.test(groupName)) ||
                   (!TARGET_HUB_JID && isGroup); // يقبل الجروب تلقائياً

const hasFile = !!fileName || messageType.includes('document') || messageType.includes('image');

return [{
  json: {
    raw: data,
    caption: caption.trim(),
    fileName,
    mimetype,
    remoteJid,
    groupName,
    isHubGroup,
    hasFile,
    base64OrMediaUrl: data.mediaUrl || data.base64 || ''
  }
}];

// استخراج وتحليل استجابة الذكاء الاصطناعي
const aiResponse = $input.first().json;
let rawText = '';
try {
  rawText = aiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('فشل استخراج الرد من نموذج الذكاء الاصطناعي: ' + e.message);
}

const cleanedJsonText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleanedJsonText);
} catch (e) {
  const match = cleanedJsonText.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
  else throw new Error('تعذر تحويل رد الذكاء الاصطناعي إلى JSON: ' + cleanedJsonText);
}

const fileInfo = $('2. التحقق من جروب البورتال والمرفق').first().json;

// خريطة بمجلدات Google Drive المعتمدة لكل مادة
const DRIVE_COURSE_FOLDERS = {
  'computer-architecture': '1cw9D5TplznX1HGf1dWh_C_-pu3ZjrJSS',
  'data-structure': '1r1e8R096dYkU5Fk-qE5bE6b-f49z8n0B',
  'operating-system': '1j3-T7wJ9oD7Lq58i7vF8tV0eG-u89R0a',
  'database-systems': '1b-7Fj7uK9zD1p8q3_W4r6eY0t129pL7M',
  'computer-graphics': '1x-9Fj8uL2qE5m8p3_R4t7eW0y123pK8L',
  'report-writing': '1q-2Lk8uJ3mE5p8r4_T5y8eQ1w234mP9N'
};

return [{
  json: {
    ...parsed,
    fileName: fileInfo.fileName,
    mimetype: fileInfo.mimetype,
    targetDriveFolderId: DRIVE_COURSE_FOLDERS[parsed.courseId] || DRIVE_COURSE_FOLDERS['computer-architecture'],
    hubRemoteJid: fileInfo.remoteJid
  }
}];

// دمج روابط درايف مع بيانات المادة
const material = $('5. تحديد مجلد Google Drive للمعيد').first().json;
const driveRes = $input.first()?.json || {};

// استخدام رابط درايف المرفوع أو المجلد المعتمد للمعيد تلقائياً
const driveId = driveRes.id || driveRes.fileId || material.targetDriveFolderId || '1cw9D5TplznX1HGf1dWh_C_-pu3ZjrJSS';
const driveViewUrl = driveRes.webViewLink || `https://drive.google.com/drive/folders/${driveId}`;
const drivePreviewUrl = driveRes.webContentLink || driveViewUrl;
const driveDownloadUrl = driveRes.webContentLink || driveViewUrl;

return [{
  json: {
    courseId: material.courseId,
    type: material.type || 'section',
    ta: material.ta || 'م. معيد المادة',
    doctor: material.doctor,
    number: material.number || 1,
    title: material.title || material.arabicTitle,
    arabicTitle: material.arabicTitle || material.title,
    fileType: material.fileType || 'pdf',
    size: driveRes.size ? `${Math.round(driveRes.size / 1024)} KB` : 'Google Drive',
    driveId,
    driveViewUrl,
    drivePreviewUrl,
    driveDownloadUrl,
    topics: material.topics || [material.arabicTitle],
    notes: material.notes || `تم الرفع آلياً من واتساب (${material.ta})`,
    hubRemoteJid: material.hubRemoteJid
  }
}];

